            double latitude = latitudeCell.getNumericCellValue();
            double longitude = longitudeCell.getNumericCellValue();
            double intensity = intensityCell.getNumericCellValue();

            // Process the data as needed
            System.out.printf("%s (%f, %f): %.2f Tesla%n", location, latitude, longitude, intensity);
        }

        workbook.close();
        file.close();
    }
}
```

