gaussian_filtered_image = imfilter(gray_image, gaussian_filter); % Apply Gaussian filter

% Define Sobel operator in x direction
sobel_x = [-1 0 1; -2 0 2; -1 0 1];

% Define Sobel operator in y direction
sobel_y = [-1 -2 -1; 0 0 0; 1 2 1];

% Apply Sobel operator in x direction
edge_image_x = conv2(double(gaussian_filtered_image), sobel_x, 'same');

% Apply Sobel operator in y direction
edge_image_y = conv2(double(gaussian_filtered_image), sobel_y, 'same');

% Combine edges in both directions
edge_image = sqrt(edge_image_x.^2 + edge_image_y.^2);

% Display edge image
imshow(edge_image);
```

In this modified code, we first create a Gaussian filter kernel using the `fspecial` function. Then, we apply the Gaussian filter to the grayscale image using the `imfilter` function. Finally, we proceed with the Sobel edge detection as before. This will help reduce the noise in the image and improve the accuracy of the edge detection.

To create a NestJS model that creates a MongoDB document with multiple schemas, follow these steps:

1. Install necessary packages:

```bash
npm install @nestjs/mongodb mongoose
```

2. Create a `schema.ts` file in your project directory:

```typescript
// schema.ts
import { Schema, Model } from 'mongoose';

const userSchema = new Schema({
  name: String,
  email: String,
  phone: Number,
});

const addressSchema = new Schema({
  street: String,
  city: String,
  state: String,
  zip: Number,
});

const orderSchema = new Schema({
  product: String,
  quantity: Number,
  price: Number,
});

export const UserModel: Model = Model('User', userSchema);
export const AddressModel: Model = Model('Address', addressSchema);
export const OrderModel: Model = Model('Order', orderSchema);
```

3. In your `app.module.ts` file, import the necessary packages and configure the MongoDB connection:

```typescript
// app.module.ts
import { Module } from '@nestjs/common';
import { MongooseModule } from '@nestjs/mongodb';

@Module({
  imports: [
    MongooseModule.forRoot('mongodb://localhost/mydatabase'),
  ],
})
export class AppModule {}
```

4. Now, you can use the `UserModel`, `AddressModel`, and `OrderModel` in your controllers or services to create and interact with the MongoDB documents. For example:

```typescript
// user.controller.ts
import { Controller, Post } from '@nestjs/common';
import { UserModel } from './schema';

@Controller('users')
export class UserController {
  constructor(private readonly userModel: UserModel) {}

  @Post()
  async createUser(userData: { name: string; email: string; phone: number }) {
    const user = await this.userModel.create(userData);
    return user;
  }
}
``

