```javascript
const mongoose = require('mongoose');

const roomSchema = new mongoose.Schema({
  propertyId: { type: mongoose.Schema.Types.ObjectId, required: true },
  number: { type: Number, required: true, unique: true },
  capacity: { type: Number, required: true },
  price: { type: Number, required: true },
  availability: { type: Array, default: [] }, // [Date]
});

const propertySchema = new mongoose.Schema({
  name: { type: String, required: true },
  address: { type: String, required: true },
  contactInfo: { type: String, required: true },
  rooms: [roomSchema],
});

const reservationSchema = new mongoose.Schema({
  guestName: { type: String, required: true },
  email: { type: String, required: true },
  phone: { type: String, required: true },
  checkInDate: { type: Date, required: true },
  checkOutDate: { type: Date, required: true },
  roomNumber: { type: Number, required: true },
  propertyId: { type: mongoose.Schema.Types.ObjectId, ref: 'Property' },
});

const Hotel = mongoose.model('Hotel', propertySchema);
const Room = mongoose.model('Room', roomSchema);
const Reservation = mongoose.model('Reservation', reservationSchema);

module.exports = { Hotel, Room, Reservation };
```

This schema includes three models: `Hotel`, `Room`, and `Reservation`. The `Hotel` model represents a hotel property with its name, address, contact information, and a list of rooms. The `Room` model represents a single room with its number, capacity, price, and availability. The `Reservation` model represents a reservation made by a guest, including their name, email, phone, check-in date, check-out date, room number, and the associated hotel property.

