import { useCombobox } from 'downshift';
import { useState } from 'react';

interface Email {
  email: string;
}

const EmailInput: React.FC = () => {
  const [emails, setEmails] = useState<Email[]>([]);
  const [query, setQuery] = useState('');

  const searchEmails = async (prefix: string) => {
    // Replace this with your actual API call or logic to fetch emails
    const fetchedEmails = await fetch(`https://example.com/api/emails?prefix=${prefix}`);
    const data = await fetchedEmails.json();
    return data;
  };

  const { isOpen, selectedItem, getMenuProps, getComboboxProps, getInputProps } = useCombobox({
    items: emails,
    getItemPredicate: (item) => item.email.toLowerCase(),
    onSelect: (selectedItem) => setQuery(selectedItem.email),
  });

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setQuery(event.target.value);
    searchEmails(event.target.value).then((data) => setEmails(data));
  };

  return (
    <div {...getComboboxProps()}>
      <input {...getInputProps()} onChange={handleInputChange} />
      {isOpen && (
        <ul {...getMenuProps()}>
          {emails.map((email) => (
            <li key={email.email}>{email.email}</li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default EmailInput;
```

